/* @lc app=leetcode id=2654 lang=kotlin */ class Solution { fun minOperations(nums: IntArray): Int = nums.count { it == 1 }.let { ones -> if (ones > 0) nums.size - ones else (0 until nums.size).minOfOrNull { i -> (i until nums.size).fold(0 to 1000000) { (g, l), j -> (if (g == 0) nums[j] else kotlin.DeepRecursiveFunction<Pair<Int, Int>, Int> { (a, b) -> if (b == 0) a else callRecursive(b to a % b) }.invoke(g to nums[j])).let { ng -> if (ng == 1) 1 to Math.min(l, j - i + nums.size - 1) else ng to l } }.let { if (it.first == 1) it.second else 1000000 } }?.let { if (it >= 1000000) -1 else it } ?: -1 } }